SELECT jsonb_build_object('observedAt',clock_timestamp(),'tasks',coalesce(jsonb_agg(jsonb_build_object('id',t.id,'ownerId',t."userId",'issueId',t."issueId",'botId',t."botId",'stage',t.stage,'status',t.status,'revision',t.revision,'candidateId',t."candidateId",'updatedAt',t."updatedAt",'runs',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'status',r.status,'kind',r.kind,'stopReason',r."stopReason",'startedAt',r."startedAt",'finishedAt',r."finishedAt",'liveLease',coalesce(r."leaseExpiresAt">now(),false),'model',r."agentDefinition"->>'model') ORDER BY r."createdAt"),'[]'::jsonb) FROM agent_runs r WHERE r."userId"=t."userId" AND r."issueId"=t."issueId"))),'[]'::jsonb)) AS observation FROM factory_tasks t WHERE t.id='6e413ef7-7179-442d-ad0e-b9492cf76145' OR t.id::text LIKE '9ea956ce%'
